-  static VisitSource infer({required bool isOffroute, int? routeLine}) {
-    if (isOffroute) return VisitSource.offroute;
-    if (routeLine != null) return VisitSource.route;
-    return VisitSource.customerList;
+  /// Từ `rt.visit/history`: `source = offroute` (xin ngoại tuyến) luôn là
+  /// Ngoài tuyến; còn lại theo `in_day_route` (true/false/null).
+  static VisitSource fromServer({String? source, Object? inDayRoute}) {
+    if (source == 'offroute') return VisitSource.offroute;
+    if (inDayRoute == true) return VisitSource.route;
+    if (inDayRoute == false) return VisitSource.offroute;
+    return VisitSource.unknown;
   }
+
+  /// Lượt chỉ có ở máy: có lịch tuyến NGÀY check-in và không xin ngoại tuyến
+  /// → route; còn lại → offroute (như BE).
+  static VisitSource infer({required bool isOffroute, required bool inDayRoute}) =>
+      !isOffroute && inDayRoute ? VisitSource.route : VisitSource.offroute;
 }

