+/// Đề xuất cập nhật hồ sơ KH từ kết quả tra cứu MST/CCCD
+/// (SPEC-tra-cuu-mst-sua-kh §3.3). Hàm thuần: không đụng UI, không ghi gì.
+library;
+
+import 'tax_lookup_service.dart';
+
+/// Trường có thể đề xuất.
+enum TaxSuggestField { billingName, owner, address, name }
+
+/// Giá trị hồ sơ đang có trên form Sửa KH.
+class CustomerIdentitySnapshot {
+  const CustomerIdentitySnapshot({
+    this.name = '',
+    this.billingName = '',
+    this.owner = '',
+    this.line1 = '',
+    this.wardId,
+    this.provinceName = '',
+    this.wardName = '',
+  });
+
+  final String name;
+  final String billingName;
+  final String owner;
+  final String line1;
+  final int? wardId;
+  final String provinceName;
+  final String wardName;
+
+  String get addressText => joinAddress(line1, wardName, provinceName);
+}
+
+class TaxSuggestion {
+  const TaxSuggestion({
+    required this.field,
+    required this.label,
+    required this.current,
+    required this.suggested,
+    required this.selectedByDefault,
+  });
+
+  final TaxSuggestField field;
+  final String label;
+
+  /// Giá trị hiển thị ('' = đang trống).
+  final String current;
+  final String suggested;
+  final bool selectedByDefault;
+}
+
+/// Bỏ khoảng trắng thừa + không phân biệt hoa thường.
+String normalizeForCompare(String? v) =>
+    (v ?? '').trim().replaceAll(RegExp(r'\s+'), ' ').toLowerCase();
+
+String joinAddress(String line1, String ward, String province) => [line1, ward, province]
+    .map((s) => s.trim())
+    .where((s) => s.isNotEmpty)
+    .join(', ');
+
+/// Các trường KHÁC giữa [current] và [r]. [r] không tìm thấy → rỗng.
+List<TaxSuggestion> taxLookupSuggestions(
+  CustomerIdentitySnapshot current,
+  TaxLookupResult r,
+) {
+  if (!r.found) return const [];
+  final out = <TaxSuggestion>[];
+  final name = r.name;
+
+  bool differs(String a, String b) =>
+      normalizeForCompare(a) != normalizeForCompare(b);
+
+  if (name != null && differs(current.billingName, name)) {
+    out.add(TaxSuggestion(
+      field: TaxSuggestField.billingName,
+      label: 'Tên hoá đơn',
+      current: current.billingName.trim(),
+      suggested: name,
+      selectedByDefault: true,
+    ));
+  }
+  if (name != null && r.isHousehold && differs(current.owner, name)) {
+    out.add(TaxSuggestion(
+      field: TaxSuggestField.owner,
+      label: 'Chủ cửa hàng',
+      current: current.owner.trim(),
+      suggested: name,
+      selectedByDefault: true,
+    ));
+  }
+  // Địa chỉ: chỉ đề xuất khi BE khớp được cả Tỉnh lẫn Xã (form địa chỉ bắt
+  // buộc chọn từ danh mục hành chính).
+  final province = r.province;
+  final ward = r.ward;
+  final line1 = r.line1;
+  if (province != null && ward != null && line1 != null) {
+    if (current.wardId != ward.id || differs(current.line1, line1)) {
+      out.add(TaxSuggestion(
+        field: TaxSuggestField.address,
+        label: 'Địa chỉ',
+        current: current.addressText,
+        suggested: joinAddress(line1, ward.name, province.name),
+        selectedByDefault: true,
+      ));
+    }
+  }
+  if (name != null && differs(current.name, name)) {
+    out.add(TaxSuggestion(
+      field: TaxSuggestField.name,
+      label: 'Tên cửa hàng',
+      current: current.name.trim(),
+      suggested: name,
+      // Tên biển hiệu thường khác tên đăng ký thuế → để sale tự chọn.
+      selectedByDefault: false,
+    ));
+  }
+  return out;
+}
+
+/// Cảnh báo kèm hộp thoại: NNT ngừng hoạt động, mã thuộc KH khác.
+List<String> taxLookupWarnings(TaxLookupResult r, {required String customerCode}) {
+  if (!r.found) return const [];
+  return [
+    if (!r.isActive) 'Trạng thái thuế: ${r.status ?? 'không hoạt động'}',
+    if (r.hasExisting && r.existingCode != customerCode)
+      'KH ${r.existingCode} - ${r.existingName ?? ''} đang dùng mã này',
+  ];
+}
+
+/// Địa chỉ đăng ký dạng chữ khi BE không khớp được Xã (chỉ để tham khảo).
+String? unmatchedAddressNote(TaxLookupResult r) {
+  if (!r.found) return null;
+  if (r.province != null && r.ward != null && r.line1 != null) return null;
+  return r.address;
+}

