+import 'package:btnet_saleman/services/visit_service.dart';
+import 'package:btnet_saleman/sync/outbox_enqueuer.dart';
+import 'package:flutter_test/flutter_test.dart';
+
+import '../sync/test_helpers.dart';
+
+/// Màn "Thông tin check-in": tìm lại ảnh check-in của đúng lượt.
+void main() {
+  test('should return the local photo of the visit, then the server URL after upload',
+      () async {
+    final db = newTestDb();
+    addTearDown(db.close);
+    final svc = VisitService(db, OutboxEnqueuer(db), compressor: (f) async => f.path);
+    final uuid = await svc.openVisit(
+        customer: 7, lat: 21, lng: 105, photoPath: '/tmp/a.jpg', photoTakenAt: DateTime.now());
+
+    final before = await svc.checkinPhotoOf(uuid);
+    expect(before!.localPath, '/tmp/a.jpg');
+    expect(before.url, isNull);
+
+    final upload = await (db.select(db.outbox)..where((t) => t.type.equals('upload'))).getSingle();
+    await db.putUploadRef(clientUuid: upload.clientUuid, fileId: 'f1', url: 'https://cdn/x.jpg');
+    final after = await svc.checkinPhotoOf(uuid);
+    expect(after!.url, 'https://cdn/x.jpg');
+    expect(after.localPath, '/tmp/a.jpg');
+  });
+
+  test('should NOT return the photo of another visit', () async {
+    final db = newTestDb();
+    addTearDown(db.close);
+    final svc = VisitService(db, OutboxEnqueuer(db), compressor: (f) async => f.path);
+    await svc.openVisit(customer: 7, lat: 21, lng: 105, photoPath: '/tmp/other.jpg', photoTakenAt: DateTime.now());
+    final mine = await svc.openVisit(customer: 8, lat: 21, lng: 105);
+    expect(await svc.checkinPhotoOf(mine), isNull);
+  });
+
+  test('should ignore non-checkin uploads that reference the visit', () async {
+    final db = newTestDb();
+    addTearDown(db.close);
+    final enq = OutboxEnqueuer(db);
+    final svc = VisitService(db, enq, compressor: (f) async => f.path);
+    final uuid = await svc.openVisit(customer: 7, lat: 21, lng: 105);
+    await enq.enqueueUpload(localPath: '/tmp/display.jpg', context: 'display', ref: uuid);
+    expect(await svc.checkinPhotoOf(uuid), isNull);
+  });
+}

