+/// Camera giả: trả lần lượt các ảnh trong [queue]; null = sale huỷ camera.
+class _FakePicker extends ImagePickerPlatform with MockPlatformInterfaceMixin {
+  final List<XFile?> queue = [];
+  final List<ImageSource> sources = [];
+
+  @override
+  Future<XFile?> getImageFromSource({
+    required ImageSource source,
+    ImagePickerOptions options = const ImagePickerOptions(),
+  }) async {
+    sources.add(source);
+    return queue.isEmpty ? null : queue.removeAt(0);
+  }
+}
+
+/// Đường dẫn ảnh đang hiển thị ở ảnh thu nhỏ.
+String? shownPhotoPath(WidgetTester tester) {
+  final finder = find.descendant(
+    of: find.byKey(const Key('checkin_photo_preview')),
+    matching: find.byType(Image),
+  );
+  if (finder.evaluate().isEmpty) return null;
+  final provider = tester.widget<Image>(finder).image;
+  final file = provider is ResizeImage ? provider.imageProvider : provider;
+  return (file as FileImage).file.path;
+}
